//! Golden tests against aeon 1.6.0 (values in `goldens.rs`, generated by
//! `.planning/quick/261126-78p-aln-eldist-57-aeon-elastic-distance-fami/gen_aeon_goldens.py`)
//! plus independent invariants.

use super::goldens::{GOLDENS, MASK_GOLDENS, PAIR_GOLDENS, PX, PY, X12, X6, Y5, Y9, Z12, Z6};
use super::*;
use crate::metric::dtw::{dtw_distance, dtw_distance_windowed};

/// Window encoding used by the golden tables.
pub(super) enum W {
    None,
    Frac(f64),
    Ita(f64),
}

impl W {
    fn win(&self) -> DtwWindow {
        match *self {
            W::None => DtwWindow::None,
            W::Frac(window) => DtwWindow::SakoeChibaFraction { window },
            W::Ita(max_slope) => DtwWindow::ItakuraFraction { max_slope },
        }
    }
}

/// One aeon distance / cost-matrix / alignment-path golden.
pub(super) struct Golden {
    pub name: &'static str,
    pub params: &'static [f64],
    pub x: &'static [f64],
    pub y: &'static [f64],
    pub window: W,
    pub distance: f64,
    /// Row-major aeon cost matrix (empty = not recorded).
    pub cost: &'static [f64],
    /// aeon path (`None` where aeon cannot produce one, see generator).
    pub path: Option<&'static [(usize, usize)]>,
    pub path_distance: f64,
}

/// aeon `<name>_pairwise_distance(PX)` and `(PX, PY)`, row-major.
pub(super) struct PairGolden {
    pub name: &'static str,
    pub params: &'static [f64],
    pub window: W,
    pub self_rm: &'static [f64],
    pub cross_rm: &'static [f64],
}

/// aeon `create_bounding_matrix` golden (`T` = admissible).
pub(super) struct MaskGolden {
    pub n: usize,
    pub m: usize,
    pub window: W,
    pub rows: &'static [&'static str],
}

const TOL: f64 = 1e-10;

fn close(a: f64, b: f64) -> bool {
    if a.is_infinite() || b.is_infinite() {
        a == b
    } else {
        (a - b).abs() <= TOL * (1.0 + b.abs())
    }
}

type Trio = (f64, FdMatrix, ElasticDistancePath);

macro_rules! trio {
    ($d:ident, $c:ident, $p:ident, $x:expr, $y:expr, $w:expr $(, $a:expr)*) => {
        Ok(($d($x, $y, $w $(, $a)*)?, $c($x, $y, $w $(, $a)*)?, $p($x, $y, $w $(, $a)*)?))
    };
}

fn edr_eps(p: &[f64]) -> Option<f64> {
    if p[0].is_nan() {
        None
    } else {
        Some(p[0])
    }
}

fn run(name: &str, p: &[f64], x: &[f64], y: &[f64], w: DtwWindow) -> Result<Trio, FdarError> {
    match name {
        "ddtw" => trio!(
            ddtw_distance,
            ddtw_cost_matrix,
            ddtw_alignment_path,
            x,
            y,
            w
        ),
        "wdtw" => trio!(
            wdtw_distance,
            wdtw_cost_matrix,
            wdtw_alignment_path,
            x,
            y,
            w,
            p[0]
        ),
        "wddtw" => trio!(
            wddtw_distance,
            wddtw_cost_matrix,
            wddtw_alignment_path,
            x,
            y,
            w,
            p[0]
        ),
        "adtw" => trio!(
            adtw_distance,
            adtw_cost_matrix,
            adtw_alignment_path,
            x,
            y,
            w,
            p[0]
        ),
        "erp" => trio!(
            erp_distance,
            erp_cost_matrix,
            erp_alignment_path,
            x,
            y,
            w,
            p[0]
        ),
        "edr" => trio!(
            edr_distance,
            edr_cost_matrix,
            edr_alignment_path,
            x,
            y,
            w,
            edr_eps(p)
        ),
        "twe" => trio!(
            twe_distance,
            twe_cost_matrix,
            twe_alignment_path,
            x,
            y,
            w,
            p[0],
            p[1]
        ),
        "msm" => trio!(
            msm_distance,
            msm_cost_matrix,
            msm_alignment_path,
            x,
            y,
            w,
            p[0],
            p[1] == 1.0
        ),
        "lcss" => trio!(
            lcss_distance,
            lcss_cost_matrix,
            lcss_alignment_path,
            x,
            y,
            w,
            p[0]
        ),
        _ => unreachable!("unknown distance {name}"),
    }
}

fn run_pair(
    name: &str,
    p: &[f64],
    a: &FdMatrix,
    b: Option<&FdMatrix>,
    w: DtwWindow,
) -> Result<FdMatrix, FdarError> {
    match name {
        "ddtw" => ddtw_pairwise_distance(a, b, w),
        "wdtw" => wdtw_pairwise_distance(a, b, w, p[0]),
        "wddtw" => wddtw_pairwise_distance(a, b, w, p[0]),
        "adtw" => adtw_pairwise_distance(a, b, w, p[0]),
        "erp" => erp_pairwise_distance(a, b, w, p[0]),
        "edr" => edr_pairwise_distance(a, b, w, edr_eps(p)),
        "twe" => twe_pairwise_distance(a, b, w, p[0], p[1]),
        "msm" => msm_pairwise_distance(a, b, w, p[0], p[1] == 1.0),
        "lcss" => lcss_pairwise_distance(a, b, w, p[0]),
        _ => unreachable!("unknown distance {name}"),
    }
}

fn matrix_from_rows<const M: usize>(rows: &[[f64; M]]) -> FdMatrix {
    let n = rows.len();
    let mut out = FdMatrix::zeros(n, M);
    for (i, r) in rows.iter().enumerate() {
        for (j, &v) in r.iter().enumerate() {
            out[(i, j)] = v;
        }
    }
    out
}

fn assert_matrix_rm(name: &str, got: &FdMatrix, want_rm: &[f64]) {
    let (r, c) = got.shape();
    assert_eq!(r * c, want_rm.len(), "{name}: shape {r}x{c}");
    for i in 0..r {
        for j in 0..c {
            let (g, w) = (got[(i, j)], want_rm[i * c + j]);
            assert!(close(g, w), "{name}: entry ({i},{j}) got {g}, aeon {w}");
        }
    }
}

#[test]
fn aeon_distance_cost_path_goldens() {
    let mut checked_paths = 0;
    for (k, g) in GOLDENS.iter().enumerate() {
        let tag = format!("#{k} {} {:?}", g.name, g.params);
        let (d, cm, path) = run(g.name, g.params, g.x, g.y, g.window.win())
            .unwrap_or_else(|e| panic!("{tag}: {e:?}"));
        assert!(
            close(d, g.distance),
            "{tag}: distance {d} vs aeon {}",
            g.distance
        );
        if !g.cost.is_empty() {
            assert_matrix_rm(&tag, &cm, g.cost);
        }
        if let Some(want) = g.path {
            assert_eq!(path.path, want, "{tag}: path");
            assert!(
                close(path.distance, g.path_distance),
                "{tag}: path distance {} vs aeon {}",
                path.distance,
                g.path_distance
            );
            checked_paths += 1;
        }
    }
    // 16 parameter sets x 9 configurations; 9 paths aeon cannot produce.
    assert_eq!(GOLDENS.len(), 16 * 9);
    assert_eq!(checked_paths, GOLDENS.len() - 9);
}

#[test]
fn aeon_pairwise_goldens() {
    let px = matrix_from_rows(&PX);
    let py = matrix_from_rows(&PY);
    for g in PAIR_GOLDENS {
        let w = g.window.win();
        let s = run_pair(g.name, g.params, &px, None, w).unwrap();
        assert_matrix_rm(g.name, &s, g.self_rm);
        let c = run_pair(g.name, g.params, &px, Some(&py), w).unwrap();
        assert_matrix_rm(g.name, &c, g.cross_rm);
        // Pairwise entries equal the pointwise distance exactly.
        for i in 0..4 {
            for j in 0..3 {
                let (d, _, _) = run(g.name, g.params, &PX[i], &PY[j], w).unwrap();
                assert_eq!(d.to_bits(), c[(i, j)].to_bits(), "{} ({i},{j})", g.name);
            }
        }
    }
}

#[test]
fn aeon_bounding_matrix_goldens() {
    for g in MASK_GOLDENS {
        let mask = g.window.win().mask(g.n, g.m).unwrap();
        let got: Vec<String> = mask
            .iter()
            .map(|r| r.iter().map(|&t| if t { 'T' } else { 'F' }).collect())
            .collect();
        assert_eq!(got, g.rows, "mask {}x{}", g.n, g.m);
    }
}

#[test]
fn fraction_window_equals_tslearn_band_for_equal_lengths() {
    for n in [5usize, 8, 13] {
        for window in [0.0, 0.1, 0.3, 0.5, 0.9] {
            let radius = (window * n as f64) as usize;
            let a = DtwWindow::SakoeChibaFraction { window }.mask(n, n).unwrap();
            let b = DtwWindow::SakoeChiba { radius }.mask(n, n).unwrap();
            assert_eq!(a, b, "n={n} window={window}");
        }
        let full = DtwWindow::SakoeChibaFraction { window: 1.0 }
            .mask(n, n + 3)
            .unwrap();
        assert_eq!(full, DtwWindow::None.mask(n, n + 3).unwrap());
    }
}

#[test]
fn adtw_zero_penalty_is_squared_dtw() {
    for (x, y) in [
        (&X6[..], &Y5[..]),
        (&X12[..], &Y9[..]),
        (&X12[..], &Z12[..]),
    ] {
        let a = adtw_distance(x, y, DtwWindow::None, 0.0).unwrap();
        let d = dtw_distance(x, y, 2.0, x.len().max(y.len()));
        assert!((a - d).abs() <= 1e-12 * (1.0 + d), "{a} vs {d}");
        let w = DtwWindow::SakoeChiba { radius: 2 };
        let a = adtw_distance(x, y, w, 0.0).unwrap();
        let d = dtw_distance_windowed(x, y, 2.0, w).unwrap();
        assert!((a - d).abs() <= 1e-12 * (1.0 + d));
        // A positive penalty never decreases the distance.
        assert!(adtw_distance(x, y, DtwWindow::None, 0.5).unwrap() >= a - 1e-12);
    }
}

#[test]
fn ddtw_is_dtw_on_hand_derivative() {
    // q'_i = ((q_i - q_{i-1}) + (q_{i+1} - q_{i-1}) / 2) / 2.
    let x = [1.0, 2.0, 2.0, 3.0, 3.0, 3.0, 4.0];
    let dx = [0.75, 0.25, 0.75, 0.0, 0.25];
    assert_eq!(slope_derivative(&x), dx);
    let y = [0.0, 1.0, 3.0, 2.0, 2.5];
    let dy = slope_derivative(&y);
    let want = dtw_distance(&dx, &dy, 2.0, 10);
    let got = ddtw_distance(&x, &y, DtwWindow::None).unwrap();
    assert!((got - want).abs() < 1e-14);
    let cm = ddtw_cost_matrix(&x, &y, DtwWindow::None).unwrap();
    assert_eq!(cm.shape(), (5, 3));
}

#[test]
fn wdtw_zero_g_is_half_dtw() {
    let d = dtw_distance(&X12, &Y9, 2.0, 12);
    let w = wdtw_distance(&X12, &Y9, DtwWindow::None, 0.0).unwrap();
    assert!((w - 0.5 * d).abs() < 1e-12 * (1.0 + d));
}

#[test]
fn identity_and_symmetry() {
    let w = DtwWindow::SakoeChibaFraction { window: 0.3 };
    for name in [
        "ddtw", "wdtw", "wddtw", "adtw", "erp", "edr", "twe", "msm", "lcss",
    ] {
        let p: &[f64] = match name {
            "twe" => &[0.001, 1.0],
            "msm" => &[1.0, 1.0],
            "edr" => &[f64::NAN],
            "ddtw" => &[],
            _ => &[0.5],
        };
        let (d0, _, path0) = run(name, p, &X12, &X12, w).unwrap();
        assert!(d0.abs() < 1e-12, "{name}: d(x, x) = {d0}");
        if name != "lcss" {
            let diag: Vec<(usize, usize)> = (0..path0.path.len()).map(|k| (k, k)).collect();
            assert_eq!(path0.path, diag, "{name}: identity path");
        }
        let (a, _, _) = run(name, p, &X12, &Z12, w).unwrap();
        let (b, _, _) = run(name, p, &Z12, &X12, w).unwrap();
        assert!((a - b).abs() < 1e-12 * (1.0 + a), "{name}: {a} vs {b}");
    }
}

#[test]
fn lcss_path_terminates_where_aeon_loops() {
    let w = DtwWindow::SakoeChibaFraction { window: 0.0 };
    for eps in [1.0, 0.4] {
        let res = lcss_alignment_path(&X12, &Z12, w, eps).unwrap();
        let bounds = w.row_bounds(12, 12).unwrap();
        for &(i, j) in &res.path {
            assert!(in_band(&bounds, i, j) && (X12[i] - Z12[j]).abs() <= eps);
        }
        assert!(res
            .path
            .windows(2)
            .all(|p| p[0].0 < p[1].0 && p[0].1 < p[1].1));
    }
}

#[test]
fn error_paths() {
    let w = DtwWindow::None;
    assert!(matches!(
        ddtw_distance(&[1.0, 2.0], &[1.0, 2.0, 3.0], w),
        Err(FdarError::InvalidDimension { .. })
    ));
    assert!(matches!(
        wdtw_distance(&[], &[1.0], w, 0.05),
        Err(FdarError::InvalidDimension { .. })
    ));
    assert!(matches!(
        wdtw_distance(&[1.0], &[1.0], w, f64::NAN),
        Err(FdarError::InvalidParameter { .. })
    ));
    assert!(matches!(
        twe_distance(&[1.0], &[1.0], w, -1.0, 1.0),
        Err(FdarError::InvalidParameter { .. })
    ));
    assert!(matches!(
        lcss_distance(&[1.0], &[1.0], w, -0.1),
        Err(FdarError::InvalidParameter { .. })
    ));
    assert!(matches!(
        edr_distance(&[1.0], &[1.0], w, Some(f64::INFINITY)),
        Err(FdarError::InvalidParameter { .. })
    ));
    for bad in [
        DtwWindow::SakoeChibaFraction { window: 1.5 },
        DtwWindow::SakoeChibaFraction { window: -0.1 },
        DtwWindow::ItakuraFraction {
            max_slope: f64::NAN,
        },
        DtwWindow::ItakuraFraction { max_slope: 0.1 },
    ] {
        assert!(matches!(
            msm_distance(&X6, &Z6, bad, 1.0, true),
            Err(FdarError::InvalidParameter { .. })
        ));
    }
    let short = FdMatrix::zeros(3, 2);
    assert!(matches!(
        ddtw_pairwise_distance(&short, None, w),
        Err(FdarError::InvalidDimension { .. })
    ));
    let empty = erp_pairwise_distance(&FdMatrix::zeros(0, 4), None, w, 0.0).unwrap();
    assert_eq!(empty.shape(), (0, 0));
}

/// Independent cross-check: tsdistances 0.1.9 (Rust core, ACM TOMS Alg. 1061),
/// `<name>_distance(X12, Y9)` with default parameters and `band = 1.0`.
#[test]
fn tsdistances_cross_check() {
    let w = DtwWindow::None;
    let cases = [
        (ddtw_distance(&X12, &Y9, w).unwrap(), 1.9932400369594838),
        (
            wdtw_distance(&X12, &Y9, w, 0.05).unwrap(),
            6.716023270766824,
        ),
        (
            adtw_distance(&X12, &Y9, w, 1.0).unwrap(),
            24.573830955653797,
        ),
        (erp_distance(&X12, &Y9, w, 0.0).unwrap(), 9.083635054707027),
        (
            lcss_distance(&X12, &Y9, w, 1.0).unwrap(),
            0.2222222222222222,
        ),
        (
            msm_distance(&X12, &Y9, w, 1.0, true).unwrap(),
            13.967632633358857,
        ),
        (
            twe_distance(&X12, &Y9, w, 0.001, 1.0).unwrap(),
            19.118642205147207,
        ),
    ];
    for (k, (got, want)) in cases.into_iter().enumerate() {
        assert!(close(got, want), "case {k}: {got} vs tsdistances {want}");
    }
}
